from __future__ import annotations

import pytest

from tests.llm_router.support.fault_server import (
    ScriptedHTTPServer,
    ScriptedResponse,
)
from tests.llm_router.support.workers.retry import (
    openai_chat_path,
    openai_success_response,
)
from tests.llm_router.support.workers.timeout import run_timeout_inprocess

pytestmark = pytest.mark.verification_kind("unit")

_PATH = openai_chat_path()

_SLOW_SECONDS = 1.5

_HEADERS = {"Content-Type": "application/json"}


def _slow(text: str) -> ScriptedResponse:
    return ScriptedResponse(
        status_code=200,
        headers=_HEADERS,
        body=openai_success_response(text=text),
        delay_seconds=_SLOW_SECONDS,
    )


def _fast(text: str) -> ScriptedResponse:
    return ScriptedResponse(
        status_code=200,
        headers=_HEADERS,
        body=openai_success_response(text=text),
    )


@pytest.mark.verifies("REQ_ROUTE_TIMEOUT_FALLBACK[revision==1]")
def test_sync_timeout_with_fallback_succeeds() -> None:
    """A slow route timing out falls back to a fast route and succeeds."""
    routes = {
        ("POST", _PATH): [
            _slow("slow answer"),
            _fast("fast answer"),
        ]
    }
    with ScriptedHTTPServer(port=0, routes=routes) as server:
        result = run_timeout_inprocess(
            scenario="fallback",
            server_base_url=server.base_url,
        )

    assert result.ok is True
    assert result.output_text == "fast answer"
